 "content": "def transform(grid):
    """Extend the observed diagonal color cycle across the whole grid."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    observed = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                observed[c - r] = color

    # The source contains parallel diagonal stripes. Find the shortest period
    # in the diagonal offset that is consistent with every visible stripe.
    period = 1
    for p in range(1, max(h, w) + 1):
        by_residue = {}
        consistent = True
        for offset, color in observed.items():
            residue = offset % p
            if residue in by_residue and by_residue[residue] != color:
                consistent = False
                break
            by_residue[residue] = color
        if consistent:
            period = p
            break

    by_residue = {offset % period: color for offset, color in observed.items()}
    # For a well-formed task every residue in the period is represented.
    return [[by_residue[(c - r) % period] for c in range(w)] for r in range(h)]
